+                    _ => crate::panes::terminal_character::NamedColor::BrightWhite,
+                };
+                ansi_to_rgb(AnsiCode::NamedColor(named))
+            } else if idx < 232 {
+                let idx = idx - 16;
+                let r = (idx / 36) * 51;
+                let g = ((idx % 36) / 6) * 51;
