25	impl DimUnfocused {
26	    fn reload_shader(&mut self) {
27	        if let Some(ref path) = self.shader_file {
28	            let host_path = PathBuf::from("/host").join(path);
29	            if let Ok(contents) = std::fs::read(&host_path) {
30	                self.shader_wasm = contents;
31	                // Re-send to all currently dimmed panes
32	                for &(id, is_plugin) in &self.dimmed_panes {
33	                    let pane_id = if is_plugin {
34	                        PaneId::Plugin(id)
35	                    } else {
36	                        PaneId::Terminal(id)
37	                    };
38	                    set_pane_shader(pane_id, Some(self.shader_wasm.clone()));
39	                }
40	            }
41	        }
42	    }
43	}
