45	impl ZellijPlugin for DimUnfocused {
46	    fn load(&mut self, configuration: BTreeMap<String, String>) {
47	        // If shader_file is set, load from file (with live-reload).
48	        // Otherwise use the built-in compiled shader.
49	        if let Some(path) = configuration.get("shader_file") {
50	            self.shader_file = Some(PathBuf::from(path));
51	        }
52	
53	        self.shader_wasm = SHADER_WASM.to_vec();
54	
55	        request_permission(&[
56	            PermissionType::ReadApplicationState,
57	            PermissionType::ChangeApplicationState,
58	        ]);
59	        subscribe(&[
60	            EventType::PaneUpdate,
61	            EventType::PermissionRequestResult,
62	            EventType::FileSystemUpdate,
63	            EventType::FileSystemCreate,
64	        ]);
65	
66	        // Try loading from file (overrides default if present)
67	        self.reload_shader();
68	
69	        if self.shader_file.is_some() {
70	            watch_filesystem();
71	        }
72	    }
73	
74	    fn update(&mut self, event: Event) -> bool {
75	        match event {
76	            Event::PermissionRequestResult(PermissionStatus::Granted) => {},
77	            Event::FileSystemUpdate(paths) | Event::FileSystemCreate(paths) => {
78	                if let Some(ref shader_path) = self.shader_file {
79	                    let host_path = PathBuf::from("/host").join(shader_path);
80	                    if paths.iter().any(|(p, _)| p == &host_path) {
81	                        self.reload_shader();
82	                    }
83	                }
84	            },
85	            Event::PaneUpdate(pane_manifest) => {
86	                // Every real (non-plugin) pane still present, INCLUDING collapsed
87	                // stack members. Since zellij 0.44's stack-list UI, collapsing a
88	                // stacked pane moves it into the server's suppressed_panes and it
89	                // reports is_suppressed=true while keeping whatever shader we last
90	                // set on it. If we dropped such a pane from `dimmed_panes` while it
91	                // was suppressed, then on re-expand-with-focus the remove() below
92	                // would return false, we'd skip the un-dim, and the now-active pane
93	                // would stay dark. So keep suppressed panes tracked and only prune a
94	                // key once its pane is actually gone (closed => absent from manifest).
95	                let mut present: std::collections::HashSet<(u32, bool)> =
96	                    std::collections::HashSet::new();
97	
98	                for (_tab_id, panes) in &pane_manifest.panes {
99	                    for pane in panes {
100	                        if pane.is_plugin {
101	                            continue;
102	                        }
103	
104	                        let pane_key = (pane.id, pane.is_plugin);
105	                        present.insert(pane_key);
106	
107	                        // Collapsed stack members aren't rendered; leave their
108	                        // shader as-is (still tracked above) until they reappear.
109	                        if pane.is_suppressed {
110	                            continue;
111	                        }
112	
113	                        let pane_id = if pane.is_plugin {
114	                            PaneId::Plugin(pane.id)
115	                        } else {
116	                            PaneId::Terminal(pane.id)
117	                        };
118	
119	                        if pane.is_focused {
120	                            if self.dimmed_panes.remove(&pane_key) {
121	                                set_pane_shader(pane_id, None);
122	                            }
123	                        } else if self.dimmed_panes.insert(pane_key) {
124	                            set_pane_shader(
125	                                pane_id,
126	                                Some(self.shader_wasm.clone()),
127	                            );
128	                        }
129	                    }
130	                }
131	
132	                self.dimmed_panes.retain(|k| present.contains(k));
133	            },
