#!/usr/bin/env perl
# For each LEFTPANE/RIGHTPANE occurrence in a raw terminal stream, report the
# most recent truecolor foreground SGR that was in effect. Lets us say which
# pane was being dimmed at each point in the stream.
use strict;
use warnings;

my ($file, $from, $to) = @ARGV;
$from //= 0;
$to   //= -1;

open my $fh, '<:raw', $file or die "open $file: $!";
local $/;
my $data = <$fh>;
close $fh;

$to = length($data) if $to < 0;
$data = substr($data, $from, $to - $from);

my $cur = 'none';
my @events;
while ($data =~ /\G(.*?)(?:\e\[38;2;(\d+);(\d+);(\d+)m|(LEFTPANE|RIGHTPANE))/gs) {
    if (defined $2) {
        $cur = "$2;$3;$4";
    } elsif (defined $5) {
        push @events, [$5, $cur];
    }
}

my %seen;
for my $e (@events) {
    my ($pane, $col) = @$e;
    $seen{$pane}{$col}++;
}
for my $pane (sort keys %seen) {
    my @cols = sort keys %{ $seen{$pane} };
    printf "%-10s -> %s\n", $pane, join(', ', @cols);
}
print "(no pane text in this window)\n" unless %seen;

